function iniParse(text){
  var root={}, cur=root;
  var lines=text.split('\n');
  for(var li=0; li<lines.length; li++){
    var line=lines[li].trim();
    if(line==='' || line.charAt(0)===';' || line.charAt(0)==='#') continue;
    if(line.charAt(0)==='['){
      var close=line.lastIndexOf(']');
      var sec=line.slice(1,close).trim();
      if(!root[sec]) root[sec]={};
      cur=root[sec];
      continue;
    }
    var eq=line.indexOf('=');
    if(eq<0) continue;
    var k=line.slice(0,eq).trim();
    var v=line.slice(eq+1).trim();
    if(v.charAt(0)==='"' && v.charAt(v.length-1)==='"') v=v.slice(1,-1);
    cur[k]=v;
  }
  return root;
}
function iniStringify(obj){
  var out=[];
  for(var sec in obj){
    if(!obj.hasOwnProperty(sec)) continue;
    out.push('['+sec+']');
    var t=obj[sec];
    for(var k in t){ if(t.hasOwnProperty(k)) out.push(k+'='+t[k]); }
    out.push('');
  }
  return out.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { iniParse:iniParse, iniStringify:iniStringify };
}
if (typeof window !== 'undefined') {
  window.IniForgePure = { iniParse:iniParse, iniStringify:iniStringify };
}
